function encode(s) {
  var out = "";
  var i = 0;
  while (i < s.length) {
    var c = s.charAt(i);
    var run = 0;
    while (i < s.length && s.charAt(i) === c) {
      run++;
      i++;
    }
    out += c + run;
  }
  return out;
}

console.log(encode("wwwwbbbw"));
